const cust = await api.get("/customers", {});
const mails = await api.get("/mails", {});
const delayed = cust.items.filter(c => c.order && c.order.status === "delayed");
const complaintIds = new Set(mails.items.filter(m => m.label === "complaint" && m.customer_id).map(m => m.customer_id));
const result = delayed.filter(c => complaintIds.has(c.id)).map(c => ({ id: c.id, name: c.name, order: c.order.order_id }));
return { totalCustomers: cust.count, totalMails: mails.count, delayedCount: delayed.length, result };
